using System;using System.Reflection;using NUnit.Framework;
namespace LWS.TruckBakeOff.Tests {
 public sealed class BakeRulesTests {
  object r;Type t,ingredient;const BindingFlags Any=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
  object Call(string n,params object[] a)=>t.GetMethod(n).Invoke(r,a);T Get<T>(string n)=>t.GetField(n,Any)!=null?(T)t.GetField(n,Any).GetValue(r):(T)t.GetProperty(n).GetValue(r);object I(int i)=>Enum.ToObject(ingredient,i);void Tick(float seconds){for(int i=0;i<Math.Ceiling(seconds/.05f);i++)Call("Tick",.05f);}void Measure(int s=0){for(int k=0;k<4;k++)Call("Measure",s,I(k),new[]{.8f,.5f,.3f,1}[k]);}void Mixed(int s=0){Measure(s);for(int i=0;i<165;i++)Call("Mix",s,.05f,true);}void Cooked(int s=0){Mixed(s);Call("LoadPan",s,2.6f);for(int i=0;i<205;i++)Call("Heat",s,.05f,200f,true);}void Decorated(int s=0){Cooked(s);for(int q=0;q<4;q++)Call("Decorate",s,q,.05f);}int Judge(int s=0,bool settled=true,bool intact=true,float retained=2.6f)=>(int)Call("Judge",s,settled,intact,retained);
  [SetUp]public void Reset(){t=Type.GetType("LWS.TruckBakeOff.BakeRules, Assembly-CSharp",true);ingredient=t.Assembly.GetType("LWS.TruckBakeOff.BakeIngredient",true);r=Activator.CreateInstance(t);Call("Reset",4,0);}
  [Test]public void CountdownInvalidSlotsAndNonfiniteAmountsDoNotMeasure(){Assert.That((bool)Call("Measure",0,I(0),.8f),Is.False);Tick(3.1f);foreach(float bad in new[]{-1f,0,float.NaN,float.PositiveInfinity})Assert.That((bool)Call("Measure",0,I(0),bad),Is.False);Assert.That((bool)Call("Measure",4,I(0),1f),Is.False);Assert.That(Get<float[,]>("measured")[0,0],Is.Zero);Assert.That(Get<int[]>("points"),Is.All.Zero);}
  [Test]public void EveryActualRecipeIngredientRequiredBeforeWhisk(){Tick(3.1f);for(int k=0;k<3;k++)Call("Measure",0,I(k),1f);for(int i=0;i<200;i++)Call("Mix",0,.1f,true);Assert.That(Get<float[]>("mixSeconds")[0],Is.Zero);Assert.That(Judge(),Is.Zero);}
  [Test]public void WhiskOutsideNativeBowlCannotMix(){Tick(3.1f);Measure();for(int i=0;i<200;i++)Call("Mix",0,.1f,false);Assert.That(Get<float[]>("mixSeconds")[0],Is.Zero);Assert.That((bool)Call("LoadPan",0,2.6f),Is.False);}
  [Test]public void EightActualContactSecondsUnlockOnlyMixedBatter(){Tick(3.1f);Mixed();Assert.That(Get<Array>("stages").GetValue(0).ToString(),Is.EqualTo("Mixed"));Assert.That(Get<int[]>("points"),Is.All.Zero);Assert.That((bool)Call("Measure",0,I(0),1f),Is.False);}
  [Test]public void EmptyPanOrOpenColdOrUnsupportedOvenCannotBake(){Tick(3.1f);Mixed();Call("LoadPan",0,2f);for(int i=0;i<250;i++)Call("Heat",0,.1f,200f,true);Assert.That(Get<float[]>("heatSeconds")[0],Is.Zero);Call("LoadPan",0,.2f);for(int i=0;i<250;i++){Call("Heat",0,.1f,149f,true);Call("Heat",0,.1f,200f,false);}Assert.That(Get<float[]>("heatSeconds")[0],Is.Zero);Assert.That(Judge(),Is.Zero);}
  [Test]public void FourRealQuadrantDosesRequiredAndNoEarlyPresentation(){Tick(3.1f);Cooked();for(int q=0;q<3;q++)Call("Decorate",0,q,.05f);Assert.That(Judge(),Is.Zero);Assert.That((bool)Call("Decorate",0,3,.001f),Is.False);Call("Decorate",0,3,.05f);Assert.That(Get<int[]>("decorated")[0],Is.EqualTo(15));Assert.That(Judge(),Is.GreaterThan(0));}
  [Test]public void BrokenUnsettledOrSpilledCakeCannotScore(){Tick(3.1f);Decorated();Assert.That(Judge(settled:false),Is.Zero);Assert.That(Judge(intact:false),Is.Zero);Assert.That(Judge(retained:1.79f),Is.Zero);Assert.That(Get<int[]>("points"),Is.All.Zero);}
  [Test]public void RealJudgingIsOnceOnlyAndOwnedByActualSlot(){Tick(3.1f);Decorated(2);int score=Judge(2);Assert.That(score,Is.EqualTo(300));Assert.That(Judge(2),Is.Zero);Assert.That(Judge(0),Is.Zero);Assert.That(Get<int[]>("points")[2],Is.EqualTo(300));}
  [Test]public void OvermeasuringAndOverbakingLowerActualQuality(){Tick(3.1f);Decorated();int clean=Judge();Call("Measure",1,I(0),1.6f);Decorated(1);for(int i=0;i<300;i++)Call("Heat",1,.05f,200f,true);Assert.That(Judge(1),Is.LessThan(clean));}
  [Test]public void NativeFailureEndsOnlyThatBatchWithoutFakePoints(){Tick(3.1f);Call("Fail",1);Decorated(0);Judge(0);Assert.That(Get<bool[]>("failed")[1],Is.True);Assert.That(Get<int[]>("points")[1],Is.Zero);Assert.That((bool)Call("Measure",1,I(0),1f),Is.False);Assert.That(Get<bool>("Complete"),Is.False);}
  [Test]public void ActualTiesAndFinishedBatchesAllowFiveSecondResultWindow(){Call("Reset",2,0);Tick(3.1f);Decorated(0);Decorated(1);Judge(0);Judge(1);Assert.That((int)Call("Place",0),Is.EqualTo(1));Assert.That((int)Call("Place",1),Is.EqualTo(1));Tick(.2f);Assert.That(Get<bool>("Complete"),Is.False);Tick(5.2f);Assert.That(Get<bool>("Complete"),Is.True);}
  [Test]public void InvalidClockTimeoutAndRematchPreserveFiniteState(){Call("Tick",float.NaN);Call("Tick",float.PositiveInfinity);Assert.That(Get<float>("Clock"),Is.Zero);Tick(305);Assert.That(Get<bool>("Complete"),Is.True);Call("Reset",4,1);Assert.That(Get<float>("Remaining"),Is.EqualTo(420));Assert.That(Get<int[]>("points"),Is.All.Zero);Assert.That(Get<float[]>("heatSeconds"),Is.All.Zero);Assert.That(Get<int[]>("decorated"),Is.All.Zero);Assert.That(Get<bool>("Complete"),Is.False);}
 }
}
